import json,re,html
from html.parser import HTMLParser
s=json.load(open('source.json'));a=json.load(open('answer.json'));r=json.load(open('reference-targets.json'))
def plain(x):return html.unescape(re.sub('<["'^>]*>'"','',x or ''))
errors=[]
allowed=set('p br table thead tbody tfoot tr th td b strong i em u sup sub ul ol li div span blockquote'.split())
class Check(HTMLParser):
 def handle_starttag(self,t,attrs):
  if t not in allowed: errors.append(('tag',t))
  for k,v in attrs:
   if k not in ['rowspan','colspan'] or not v.isdigit():errors.append(('attr',t,k,v))
assert len(a)==len(s)==12
for i,(src,row) in enumerate(zip(s,a)):
 for k in ['code_id','source_id','source_sha256','number']:assert row[k]==src[k]
 for field in ['assessment','scope_limitations','new_burdens_review']:assert len(row['substantive_impact'][field])>=40
 assert row['substantive_impact']['version']==1
 if src['benefit_check_required']:assert len(row['benefit_review'])>=100
 if row['status']=='retained_unchanged':assert row['proposed_xml'] is None and row['substantive_impact']['classification']=='retained_necessary' and row['substantive_impact']['effects']==[]
 else:
  assert row['status']=='rewrite_draft' and row['proposed_xml']
  Check().feed(row['proposed_xml'])
 if row.get('change_type')=='normative_reduction':
  assert row['reform_policy_id']=='editorial_direction_2026_10_19'
  assert all(len(x)>=30 for x in row['removed_provisions'])
 checks=row['reference_checks'];required=r['requirements'][row['code_id']+'|'+row['source_id']]
 assert [x['target_key'] for x in checks]==required
 for check in checks:
  assert check['view_sha256']==r['targets'][check['target_key']]['view_sha256']
  assert len(check['assessment'])>=80
 for e in row['substantive_impact']['effects']:
  assert re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)*',e['measure_id']) and 6<=len(e['measure_id'])<=96
  for f,txt in [('source_quote',plain(src['source_xml'])),('proposed_quote',plain(row['proposed_xml']))]:
   if len(e[f])<12 or e[f] not in txt:errors.append((row['number'],f,e[f]))
 print(row['number'],row['status'],row['substantive_impact']['classification'],len(row['reference_checks']),'references',len(row['substantive_impact']['effects']),'effects')
print('ERRORS',errors)
assert not errors
PY"

